    {"ticket": "T-203", "verdict": "needs-human", "evidence": "需求歧义: AC3 有两种读法"},
]
print("== 判定协议 ==")
for v in VERDICTS:
    print("%s: %s  证据: %s" % (v["ticket"], v["verdict"], v["evidence"]))
print("规则: 每个判定必须带证据链接, 无证据的判定无效")

